const defaults={sparks:0,distance:0,best:0,pace:1,magnet:1,shields:1,luck:1};
let save;try{save={...defaults,...JSON.parse(localStorage.getItem('neonDashSave')||'{}')}}catch{save={...defaults}}
let lane=0,visualLane=0,objects=[],spawnIn=1.5,elapsed=0, last=performance.now(), frame=0, invuln=0,combo=0,comboTimer=0,paused=false,toastTimer=0,soundOn=false,audio;
let w=0,h=0,dpr=1,stars=[];
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),fmt=n=>Math.floor(n).toLocaleString('en-US');
function persist(){try{localStorage.setItem('neonDashSave',JSON.stringify(save))}catch{}}
function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);w=r.width;h=r.height;canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);stars=Array.from({length:50},()=>({x:Math.random()*w,y:Math.random()*h*.46,r:Math.random()*1.5+.3,a:Math.random()*.5+.15}))}
new ResizeObserver(resize).observe(canvas);resize();
const upgrades={pace:{btn:'upgradePace',cost:'paceCost',field:'pace',base:20,mult:1.75},magnet:{btn:'upgradeMagnet',cost:'magnetCost',field:'magnet',base:30,mult:1.8},shield:{btn:'upgradeShield',cost:'shieldCost',field:'shields',base:60,mult:2.1}};
function costFor(key){const u=upgrades[key],lv=save[u.field]-(key==='shield'?1:1);return Math.round(u.base*Math.pow(u.mult,Math.max(0,lv)))}
function updateUI(){
 $('coins').textContent=fmt(save.sparks);$('best').textContent=fmt(save.best)+'m';$('distance').textContent=fmt(save.distance);$('paceVal').textContent=save.pace.toFixed(1)+'×';$('magnetVal').textContent=save.magnet.toFixed(1)+'×';$('shieldVal').textContent=save.shields;
 $('paceBar').style.width=Math.min(100,14+save.pace*11)+'%';$('magnetBar').style.width=Math.min(100,10+save.magnet*13)+'%';$('shieldBar').style.width=Math.min(100,save.shields*21)+'%';$('level').textContent='LVL '+(1+Math.floor((save.pace+save.magnet+save.shields-3)/2));
 for(const [key,u] of Object.entries(upgrades)){const cost=costFor(key);$(u.cost).innerHTML='✦ '+fmt(cost)+'<small>LEVEL '+save[u.field]+'</small>';$(u.btn).disabled=save.sparks<cost}
 const index=unlocks.reduce((a,x,i)=>save.best>=x.at?i:a,0),current=unlocks[index],next=unlocks[index+1];$('avatar').textContent=current.emoji;$('charName').textContent=current.name;$('charDesc').textContent=current.desc;
 if(next){const progress=clamp((save.best-current.at)/(next.at-current.at)*100,0,100);$('unlockProgress').textContent=fmt(save.best)+' / '+fmt(next.at)+'m';$('unlockBar').style.width=progress+'%';$('nextChar').textContent='Next up: '+next.name+' — '+fmt(next.at)+'m'}else{$('unlockProgress').textContent='ALL RUNNERS FOUND';$('unlockBar').style.width='100%';$('nextChar').textContent='The whole roster is yours. Legend.'}
 $('tapReward').textContent='+'+tapAmount();$('streak').textContent='⚡ '+(1+Math.min(combo,9)*.1).toFixed(1)+'× FLOW';$('combo').textContent=combo>1?'CLEAN DODGES  × '+combo:'';
}
function tapAmount(){return Math.max(1,Math.floor(save.pace*save.magnet))}
function showToast(text){const t=$('toast');t.textContent=text;t.classList.add('show');toastTimer=1.05}
function spark(amount=1){save.sparks+=amount;persist();updateUI()}
function tap(){spark(tapAmount());showToast('+'+tapAmount()+' SPARK'+(tapAmount()===1?'':'S'));if(soundOn)beep(540,.05)}
function buy(key){const u=upgrades[key],cost=costFor(key);if(save.sparks<cost)return;save.sparks-=cost;save[u.field]++;if(key==='pace')save.pace=Math.min(10,save.pace+.25);if(key==='magnet')save.magnet=Math.min(8,save.magnet+.3);persist();updateUI();showToast(key==='shield'?'SHIELD BOOSTED':'UPGRADE INSTALLED');if(soundOn)beep(720,.09)}
for(const key of Object.keys(upgrades))$(upgrades[key].btn).addEventListener('click',()=>buy(key));
$('tapBtn').addEventListener('click',tap);$('resetBtn').addEventListener('click',()=>{if(confirm('Reset all progress and start fresh?')){save={...defaults};persist();updateUI()}});
function beep(freq,duration){try{audio=audio||new AudioContext();const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=freq;o.type='sine';g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}catch{}}
$('soundBtn').addEventListener('click',()=>{$('soundBtn').textContent=soundOn?'♫':'♪';soundOn=!soundOn;if(soundOn)beep(600,.08)});
function move(dir){lane=clamp(lane+dir,-1,1);if(soundOn)beep(380,.035)}$('leftBtn').addEventListener('click',()=>move(-1));$('rightBtn').addEventListener('click',()=>move(1));
window.addEventListener('keydown',e=>{if(['ArrowLeft','a','A'].includes(e.key)){move(-1);e.preventDefault()}if(['ArrowRight','d','D'].includes(e.key)){move(1);e.preventDefault()}if(e.code==='Space'){tap();e.preventDefault()}});
let touchStart=null;const stage=$('stage');stage.addEventListener('pointerdown',e=>{touchStart={x:e.clientX,y:e.clientY};stage.setPointerCapture?.(e.pointerId)});stage.addEventListener('pointerup',e=>{if(!touchStart)return;const dx=e.clientX-touchStart.x,dy=e.clientY-touchStart.y;if(Math.abs(dx)>25){move(dx>0?1:-1)}else if(Math.abs(dy)<25)tap();touchStart=null});
function createObject(){const isSpark=Math.random()<.31;objects.push({z:82,lane:Math.floor(Math.random()*3)-1,type:isSpark?'spark':['crate','spikes','gate'][Math.floor(Math.random()*3)],spin:Math.random()*6})}
function continueRun(){paused=false;save.distance=0;lane=0;visualLane=0;objects=[];spawnIn=2;invuln=2;const m=$('modal');m.classList.remove('open');updateUI()}
$('continueBtn').addEventListener('click',continueRun);$('closeModal').addEventListener('click',continueRun);
function collision(o){if(o.z<3.6&&o.z>-1.2&&o.lane===lane){if(o.type==='spark'){spark(Math.max(1,Math.floor(save.magnet)));combo++;comboTimer=4;if(soundOn)beep(850,.08)}else if(invuln<=0){o.hit=true;if(save.shields>1){save.shields--;invuln=2;combo=0;showToast('SHIELD SAVED YOU');persist();updateUI()}else{save.best=Math.max(save.best,Math.floor(save.distance));persist();updateUI();paused=true;$('modalTitle').textContent='Watch your step!';$('modalText').textContent='You clipped a trap at '+fmt(save.distance)+'m. The track is still yours — hop back in and keep building your legend.';$('modal').classList.add('open')}}}}
function roundRect(x,y,ww,hh,r){ctx.beginPath();ctx.roundRect(x,y,ww,hh,r)}
function drawBackground(t){const sky=ctx.createLinearGradient(0,0,0,h);sky.addColorStop(0,'#102830');sky.addColorStop(.52,'#1c4244');sky.addColorStop(1,'#24413b');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);
 const horizon=h*.43;ctx.fillStyle='#b9dbac';ctx.globalAlpha=.13;ctx.beginPath();ctx.arc(w*.72,horizon*.55,Math.min(w,h)*.08,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
 for(const s of stars){ctx.fillStyle=`rgba(202,255,225,${s.a})`;ctx.fillRect(s.x,s.y,s.r,s.r)}
 // distant skyline + hills
 ctx.fillStyle='#163a3c';ctx.beginPath();ctx.moveTo(0,horizon);for(let x=0;x<=w+30;x+=30)ctx.lineTo(x,horizon-(Math.sin(x*.019)*12+Math.sin(x*.044)*6));ctx.lineTo(w,horizon+22);ctx.lineTo(0,horizon+22);ctx.fill();
 for(let side of [-1,1]){for(let i=0;i<5;i++){let bw=w*.035+i%2*4,bh=h*(.12+(i%3)*.035),x=side<0?i*(bw+5):w-(i+1)*(bw+5);let y=horizon-bh*.72;ctx.fillStyle=i%2?'#1a3b3e':'#204347';ctx.fillRect(x,y,bw,bh);ctx.fillStyle='#a5d6a5';ctx.globalAlpha=.17;for(let yy=y+9;yy<y+bh-4;yy+=12)for(let xx=x+5;xx<x+bw-4;xx+=9)ctx.fillRect(xx,yy,3,4);ctx.globalAlpha=1}}
 // ground
 ctx.fillStyle='#244842';ctx.fillRect(0,horizon,w,h-horizon);
 const roadTop=w*.16,roadBottom=w*.47,roadCenter=w/2;ctx.beginPath();ctx.moveTo(roadCenter-roadTop,horizon);ctx.lineTo(roadCenter+roadTop,horizon);ctx.lineTo(roadCenter+roadBottom,h);ctx.lineTo(roadCenter-roadBottom,h);ctx.closePath();let road=ctx.createLinearGradient(0,horizon,0,h);road.addColorStop(0,'#334c4b');road.addColorStop(1,'#1b2d32');ctx.fillStyle=road;ctx.fill();
 // shoulder strips and lane markers in perspective
 for(const s of [-1,1]){ctx.beginPath();ctx.moveTo(roadCenter+s*roadTop,horizon);ctx.lineTo(roadCenter+s*(roadTop+5),horizon);ctx.lineTo(roadCenter+s*(roadBottom+10),h);ctx.lineTo(roadCenter+s*roadBottom,h);ctx.fillStyle='#7ce1b4';ctx.globalAlpha=.6;ctx.fill();ctx.globalAlpha=1}
 for(const z of [0,.25,.5,.75,1]){const yy=horizon+(h-horizon)*z*z;ctx.strokeStyle=`rgba(181,242,207,${.04+z*.06})`;ctx.lineWidth=1+z*2;ctx.beginPath();ctx.moveTo(roadCenter-roadTop-(roadBottom-roadTop)*z,yy);ctx.lineTo(roadCenter+roadTop+(roadBottom-roadTop)*z,yy);ctx.stroke()}
 for(const laneMark of [-.333,.333]){ctx.beginPath();ctx.moveTo(roadCenter+laneMark*roadTop*2,horizon);ctx.lineTo(roadCenter+laneMark*roadBottom*2,h);ctx.strokeStyle='#c1e3c455';ctx.setLineDash([12,18]);ctx.lineWidth=1;ctx.stroke();ctx.setLineDash([])}
 // roadside lamps
 for(let i=0;i<5;i++){let z=((i/5+(t*.025)%1)%1),pers=z*z,xoff=roadTop+(roadBottom-roadTop)*pers,y=horizon+(h-horizon)*pers,scale=.35+pers;for(const side of [-1,1]){const x=roadCenter+side*(roadTop+(roadBottom-roadTop)*pers+15*scale);ctx.strokeStyle='#52736c';ctx.lineWidth=2*scale;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x,y-42*scale);ctx.lineTo(x-side*9*scale,y-45*scale);ctx.stroke();ctx.fillStyle='#ffe69c';ctx.shadowColor='#d6ffbe';ctx.shadowBlur=15*scale;ctx.beginPath();ctx.arc(x-side*9*scale,y-45*scale,3*scale,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0}}
 return {horizon,roadTop,roadBottom,roadCenter};
}

